sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var INCIDENT_TRANSFORM_MAP_SYS_ID = '9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e';

	try {
		var body = request.body.data;

		if (!body || !body.sys_id || !body.state || !body.urgency || !body.mandatory_fields) {
			response.setStatus(400);
			return {
				status: "error",
				message: "Missing required fields: sys_id and state or urgency or mandatory_fields"
			};
		}

		var importGR = new GlideRecord('x_xurre_imr_u_import_incident');
		importGR.initialize();
		importGR.setValue('operation', 'update_incident_status');
		importGR.setValue('incident_sys_id', body.sys_id);
		importGR.setValue('state_sys_id', body.state);
		importGR.setValue('urgency_sys_id', body.urgency);
		importGR.setValue('snow_priority_sys_id', body.priority || '');
		importGR.setValue('mandatory_fields', JSON.stringify(body.mandatory_fields));
		var importSysId = importGR.insert();

		importGR.get(importSysId);
		var resultStatus = importGR.getValue('result_status');
		var resultMessage = importGR.getValue('result_message');
		var resultSysId = importGR.getValue('result_sys_id');
		var resultNumber = importGR.getValue('result_number');

		if (resultStatus !== 'success') {
			response.setStatus(400);
			return { status: "error", message: resultMessage };
		}

		gs.info("Incident updated successfully");
		response.setStatus(200);
		return {
			status: "success",
			message: "Incident updated successfully",
			number: resultNumber,
			sys_id: resultSysId
		};

	} catch (err) {
		gs.info("Incident not updated successfully error: " + err.message);
		response.setStatus(400);
		return {
			status: "error",
			message: "Unexpected error occurred",
			details: err.message
		};
	}
})(request, response);
